# Generated by Descant: acceptance tests.

# frozen_string_literal: true
require "timekeeping_relay"

RSpec.describe TimekeepingRelay::IdempotencyKey do
  it "derives one stable UUID per batch body and a different one when any entry differs at the same positions" do
    batch = lambda do |entry_id, generation|
      { "schema_version" => 1,
        "snapshots" => [{ "generation" => generation, "outbox_position" => 1,
                          "entry" => { "id" => entry_id, "company_id" => 1, "version" => 1 } }] }
    end

    key = described_class.for(batch.call(10, 2))

    expect(key).to match(/\A\h{8}-\h{4}-5\h{3}-[89ab]\h{3}-\h{12}\z/)
    expect(described_class.for(batch.call(10, 2))).to eq(key)
    # Two outboxes can share positions; their different bodies must never share a key.
    expect(described_class.for(batch.call(11, 2))).not_to eq(key)
    expect(described_class.for(batch.call(10, 3))).not_to eq(key)
  end
end
